import forgelib as F
G = F.make(slug="the-forge-race-reroll-guide", order=3, kw="reroll race in the forge",
 title="How to Reroll Race in The Forge (Free Rerolls 2026)",
 h1="How to Reroll Your Race in The Forge (and Get Free Rerolls)",
 desc="How to reroll race in The Forge: where the Wizard's Tower is on each island, how the Race Menu works, the odds for every rarity, and 45 free rerolls from codes.",
 kw2=["the forge reroll race","the forge free rerolls","the forge wizard tower","the forge race menu","how to get rerolls in the forge"],
 related=["the-forge-codes","the-forge-races-guide","the-forge-archangel-race","the-forge-beginners-guide"],
 ids=["so5h2Z_odXI","ap6TlIsKHWE","APELI3KKolk","gmYPCLg-q9U","ol9sMpzbyMc","8Rx3uOjRhJU","Fxsnep5Hwho","z2SYTq_Ka0U"],
 lead="Your race is one of the biggest power boosts in the game, so knowing how to <strong>reroll race in The Forge</strong> matters. This guide shows where to reroll on every island, what the odds are, and how to get rerolls for free. It brings together all eight of Fridge's reroll videos and Shorts.",
 heading="Watch Fridge's Race Reroll Videos and Shorts",
 sections=[
 ("where","Where to Reroll Your Race","""<p>According to the Forge Wiki, you change race in the <strong>Wizard's Tower</strong> by talking to the <strong>Wizard</strong>, or from the <strong>Race Menu</strong>. The Wizard opens the Race Menu for you. Here's where he stands on each island:</p>
<div class="table-wrap"><table><caption>Wizard locations in The Forge</caption><thead><tr><th scope="col">Island</th><th scope="col">Where to find the Wizard</th></tr></thead><tbody>
<tr><td>Stonewake's Cross</td><td>Up the hill to the left of the cave, past Tomo, in a tower on the left</td></tr>
<tr><td>Forgotten Kingdom</td><td>Up the hill to the right of spawn, past Line, through a castle gate, in the tower straight ahead</td></tr>
<tr><td>Frostspire Expanse</td><td>Straight from spawn, past Wo, in a hut on the right</td></tr></tbody></table></div>"""),
 ("steps","How to Reroll, Step by Step","""<ol class="steps"><li>Walk to the Wizard's Tower on your island, or open the Race Menu.</li><li>Talk to the <strong>Wizard</strong> to open the race screen.</li><li>Press <strong>Reroll</strong>. Each press uses one reroll and gives you a random race based on the odds below.</li><li>Keep rolling until you land a race you want. Rerolls are spent even if you get a worse race.</li></ol>
<p>The <strong>Fast Roll</strong> gamepass (239 Robux) only makes the spin animation quicker. It doesn't change the odds.</p>"""),
 ("free","How to Get Free Rerolls","""<p>The wiki lists two ways to get rerolls: <strong>Robux</strong> purchases or <strong>codes</strong>. Codes are the only free source. Right now four codes work, for <strong>45 free rerolls</strong> in total:</p>
<ul><li><code>SORRYFORSHUTDOWNN!</code>: 15 rerolls</li><li><code>AIDASAYSSORRY</code>: 10 rerolls</li><li><code>FORGECOMEBACK</code>: 10 rerolls</li><li><code>TWILIGHTWAR</code>: 10 rerolls</li></ul>
<p>Redeem them in the Mailbox. The full list, with expiry notes, is on our <a href="the-forge-codes.html">The Forge codes</a> page. Fridge's \"free reroll\" Shorts all use whatever codes were active that week, and most of those have since expired.</p>"""),
 ("odds","Race Odds by Rarity","""<div class="table-wrap"><table><caption>The Forge race odds (Forge Wiki, November 11, 2026)</caption><thead><tr><th scope="col">Rarity</th><th scope="col">Chance per race</th><th scope="col">Races</th></tr></thead><tbody>
<tr><td>Common</td><td>35.05%</td><td>Human</td></tr><tr><td>Uncommon</td><td>11.5%</td><td>Elf, Zombie</td></tr><tr><td>Rare</td><td>7.5%</td><td>Goblin, Undead, Orc</td></tr><tr><td>Epic</td><td>4%</td><td>Dwarf, Shadow, Vampire</td></tr><tr><td>Legendary</td><td>1.25%</td><td>Minotaur, Dragonborn, Golem, Felynx, Fairy</td></tr><tr><td>Mythical</td><td>0.25%</td><td>Angel, Demon, Orc Lord, Dryad, Imp, Fallen Angel</td></tr><tr><td>Relic</td><td>0.1%</td><td>ArchAngel, Kitsune</td></tr></tbody></table></div>
<p>Any Legendary race comes up about 6.25% of the time, so 45 free rerolls give you roughly a 94% chance of at least one Legendary. Mythical races total 1.5%, so 45 rolls give about a 49% chance of a Mythical. Relics total 0.2%, about 9% over 45 rolls.</p>
<p class="small">The wiki's listed chances add up to just over 100% (100.5%), so treat these numbers as close estimates, not exact odds.</p>"""),
 ("luck","Do Luck Boosts Help?","""<p>No. The Forge Wiki says event luck, totem luck and potion luck <strong>don't</strong> affect race rerolls, so save your Luck Potions for mining. See what each race actually does in our <a href="the-forge-races-guide.html">races guide</a> before you decide when to stop rolling.</p>""")],
 faq=[("Where do you reroll race in The Forge?","At the Wizard's Tower. Talk to the Wizard, who opens the Race Menu, and press Reroll."),
      ("How do you get free rerolls in The Forge?","Redeem codes in the Mailbox. Four codes work right now for 45 rerolls in total."),
      ("Does luck affect race rerolls in The Forge?","No. Event, totem and potion luck don't change race odds, according to the Forge Wiki.")],
 sources=[F.wiki("Races"),F.wiki("Wizard"),F.wiki("Gamepass","Gamepasses (Fast Roll)"),F.wiki("Codes")],
 howto=("How to reroll your race in The Forge",[("Go to the Wizard","Walk to the Wizard's Tower on your island.","where"),("Open the Race Menu","Talk to the Wizard to open the race screen.","steps"),("Reroll","Press Reroll. Each press uses one reroll.","steps"),("Get more rerolls","Redeem codes in the Mailbox for free rerolls.","free")]))
